// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.QueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility.QueryModelPreparation;
import org.junit.jupiter.api.Test;

class PreparedValuesTraversalTest {

	@Test
	void preparationTraversalScalesLinearlyForDeepQueriesWithoutValues() {
		int small = preparationVisits(64);
		int large = preparationVisits(128);
		assertTrue(large <= 3L * small,
				"doubling query depth must not quadruple preparation walks: " + small + " -> " + large);
	}

	@Test
	void cachedSelectMembershipRespectsCloningReplacementAndScopeChanges() {
		Projection selected = new Projection(new SingletonSet());
		Join join = new Join(new SingletonSet(), selected);
		QueryRoot root = new QueryRoot(join);
		try (QueryModelPreparation preparation = PreparedValuesSnapshot.newPreparation()) {
			preparation.prepare(root);
			assertThat(preparation.firstSubqueryProjections(root)).containsExactly(selected);
			QueryRoot clone = root.clone();
			Projection cloneProjection = (Projection) ((Join) clone.getArg()).getRightArg();
			assertThat(preparation.firstSubqueryProjections(clone)).containsExactly(cloneProjection);
			assertThat(cloneProjection).isNotSameAs(selected);
			Projection replacement = new Projection(new SingletonSet());
			join.setRightArg(replacement);
			preparation.invalidate(join);
			preparation.prepare(root);
			assertThat(preparation.firstSubqueryProjections(root)).containsExactly(replacement);
			replacement.setSubquery(false);
			preparation.invalidate(replacement);
			assertThat(preparation.firstSubqueryProjections(root)).isEmpty();
			replacement.setSubquery(true);
			preparation.resetTraversal();
			assertThat(preparation.firstSubqueryProjections(root)).containsExactly(replacement);
		}
	}

	private static int preparationVisits(int depth) {
		AtomicInteger visits = new AtomicInteger();
		TupleExpr expression = new SingletonSet();
		for (int i = 0; i < depth; i++) {
			expression = new CountingJoin(expression, new SingletonSet(), visits);
		}
		new DefaultEvaluationStrategy(new EmptyTripleSource(), null).precompile(new QueryRoot(expression));
		return visits.get();
	}

	private static final class CountingJoin extends Join {
		private final AtomicInteger visits;

		private CountingJoin(TupleExpr left, TupleExpr right, AtomicInteger visits) {
			super(left, right);
			this.visits = visits;
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visits.incrementAndGet();
			super.visit(visitor);
		}
	}
}
